css:
/* The family portal (docs/Puppy_Parent_Portal_Plan.md section 7): the Lawn scheme of
   the AK sample, photo-led, icons in soft tinted squares, softly rounded (14px cards,
   8px buttons and inputs), light and dark following the device. Changing this file
   means bumping PORTAL_VERSION (src/portal/version.js). */

:host {
  --bg: #F5F2EA; --surface: #FFFDF8; --ink: #1E1D1A; --muted: #625C51; --line: #DED7C8;
  --accent: #34523C; --accent-ink: #FFFFFF; --accent-soft: #E3EADF; --brass: #8A6B2C; --band: #ECE6D8;
  --head: #1F3A2A; --head-ink: #F5F2EA; --head-muted: #B9C8BC; --tab-on: #CFE3C4; --tab-on-ink: #1F3A2A;
  --ok: #3E7A4B; --warn: #8A5A1E; --warn-soft: #F3E6D3; --bad: #A3261E; --bad-soft: #F6DEDB; --cal: #B5462F;
  --girl: #A8456F; --girl-soft: #F6E1EA; --boy: #2F6690; --boy-soft: #DDEAF5;
  --sand: #EFE2C3; --sand-line: #DCC79A; --sand-brass: #75591F;
  --shadow: 0 1px 2px rgba(30,29,26,.06), 0 6px 18px rgba(30,29,26,.08);
  --f-display: "Fraunces", Georgia, "Times New Roman", serif;
  --f-body: "Mulish", "Segoe UI", system-ui, -apple-system, sans-serif;
  --f-script: "Pinyon Script", "Snell Roundhand", "Apple Chancery", cursive;
  --r: 8px; --rc: 14px; --gut: 10px; color-scheme: light;
}
@media (prefers-color-scheme: dark) { :host(:not(.light)) {
  --bg: #141412; --surface: #1D1C19; --ink: #ECE7DC; --muted: #A9A294; --line: #35332D;
  --accent: #8FB998; --accent-ink: #0F1A12; --accent-soft: #233127; --brass: #CFAE66; --band: #24221E;
  --head: #10201A; --head-ink: #ECE7DC; --head-muted: #8FA596; --tab-on: #2E4A36; --tab-on-ink: #ECE7DC;
  --ok: #86C495; --warn: #E0A65A; --warn-soft: #33281A; --bad: #F08A80; --bad-soft: #3A2220; --cal: #C9583F; --girl: #E79BBB; --girl-soft: #3A2430; --boy: #8DB8DE; --boy-soft: #1F2C3A;
  --sand: #352C19; --sand-line: #4D4027; --sand-brass: #D9B870;
  --shadow: 0 1px 2px rgba(0,0,0,.4), 0 6px 18px rgba(0,0,0,.35); color-scheme: dark; } }
:host(.dark) {
  --bg: #141412; --surface: #1D1C19; --ink: #ECE7DC; --muted: #A9A294; --line: #35332D;
  --accent: #8FB998; --accent-ink: #0F1A12; --accent-soft: #233127; --brass: #CFAE66; --band: #24221E;
  --head: #10201A; --head-ink: #ECE7DC; --head-muted: #8FA596; --tab-on: #2E4A36; --tab-on-ink: #ECE7DC;
  --ok: #86C495; --warn: #E0A65A; --warn-soft: #33281A; --bad: #F08A80; --bad-soft: #3A2220; --cal: #C9583F; --girl: #E79BBB; --girl-soft: #3A2430; --boy: #8DB8DE; --boy-soft: #1F2C3A;
  --sand: #352C19; --sand-line: #4D4027; --sand-brass: #D9B870;
  --shadow: 0 1px 2px rgba(0,0,0,.4), 0 6px 18px rgba(0,0,0,.35); color-scheme: dark; }

html { font-size: 14px; -webkit-text-size-adjust: 100%; }
html[data-zoom="2"] { font-size: 16.5px; }
html[data-zoom="3"] { font-size: 19px; }
@media (min-width: 720px) { html { font-size: 15px; } html[data-zoom="2"] { font-size: 17.5px; } html[data-zoom="3"] { font-size: 20px; } }
* { box-sizing: border-box; }
.kp-body { margin: 0; background: var(--bg); color: var(--ink); font: 1rem/1.45 var(--f-body); }
.kp-body.in { padding-bottom: calc(9rem + env(safe-area-inset-bottom)); }
h1, h2, h3 { font-family: var(--f-display); font-weight: 500; line-height: 1.15; margin: 0 0 .5rem; text-wrap: balance; }
h1 { font-size: 1.6rem; } h2 { font-size: 1.15rem; } h3 { font-size: 1rem; }
p { margin: 0 0 .5rem; }
a { color: var(--accent); }
img { max-width: 100%; display: block; }
.sprite { position: absolute; }
svg.i { width: 1.3rem; height: 1.3rem; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.eyebrow { font-size: .68rem; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--brass); margin: 0 0 .3rem; }
.script { font-family: var(--f-script); font-weight: 400; font-size: 2.2rem; line-height: 1.05; }
.muted { color: var(--muted); } .small { font-size: .84rem; }
.stack { display: grid; gap: .7rem; }
.two { display: grid; grid-template-columns: 1fr 1fr; gap: .6rem; }

.top { position: sticky; top: 0; z-index: 5; display: flex; align-items: center; justify-content: space-between; gap: .6rem; padding: .6rem var(--gut); padding-top: calc(.6rem + env(safe-area-inset-top)); background: var(--head); color: var(--head-ink); }
.brand { display: flex; align-items: center; gap: .6rem; min-width: 0; color: inherit; text-decoration: none; }
.logo { position: relative; width: 2.7rem; height: 2.7rem; flex: none; border-radius: 50%; overflow: hidden; background: #fff; color: #1E1D1A; display: grid; place-items: center; }
.logo img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; background: #fff; }
.logo img.gone { display: none; }
.logo .mono { font: italic 500 1rem/1 var(--f-display); letter-spacing: -.02em; }
.logo svg.i { width: 1.6rem; height: 1.6rem; }
.bt { display: grid; min-width: 0; }
.bt b { font: 500 1.05rem/1.1 var(--f-display); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sub { display: flex; align-items: center; gap: .3rem; margin-top: 2px; font-size: .64rem; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--head-muted); }
.sub svg.i { width: .9rem; height: .9rem; }
.top-end { display: flex; align-items: center; gap: .3rem; }
.aa, .acct { display: inline-flex; align-items: center; justify-content: center; min-width: 2.6rem; min-height: 2.6rem; border: 1px solid transparent; border-radius: 50%; background: transparent; color: var(--head-ink); font: 700 .95rem var(--f-display); cursor: pointer; }
.aa:hover, .acct:hover { border-color: var(--head-muted); }
.acct svg.i { width: 1.5rem; height: 1.5rem; }

main { max-width: 64rem; margin: 0 auto; padding: var(--gut); display: grid; gap: .6rem; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--rc); padding: 1rem; }
.card.narrow { max-width: 28rem; width: 100%; margin: 2rem auto; }

label { display: grid; gap: .25rem; font-weight: 700; font-size: .86rem; }
input { font: 400 1rem var(--f-body); color: var(--ink); background: var(--surface); border: 1.5px solid var(--line); border-radius: var(--r); padding: .55rem .65rem; min-height: 2.6rem; width: 100%; }
input:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: .4rem; min-height: 2.6rem; padding: .5rem 1rem; border-radius: var(--r); font: 700 .86rem/1.1 var(--f-body); letter-spacing: .02em; border: 1.5px solid var(--accent); background: transparent; color: var(--accent); cursor: pointer; text-decoration: none; }
.btn.solid { background: var(--accent); color: var(--accent-ink); }
.btn.text { border: 0; padding: 0; min-height: 2rem; }
.btn.line:hover { background: var(--accent); color: var(--accent-ink); }
.btn.solid:hover { filter: brightness(1.08); }
.btn.onfill { background: var(--accent-ink); color: var(--accent); border-color: var(--accent-ink); }
.btn svg.i { width: 1.1rem; height: 1.1rem; }
.error { color: var(--bad); background: var(--bad-soft); border-radius: var(--r); padding: .6rem .8rem; }
.note { background: var(--accent-soft); border-radius: var(--r); padding: .6rem .8rem; }
.status { display: flex; align-items: center; gap: .35rem; font-weight: 700; }
.status.ok { color: var(--ok); }

/* Home (plan 7.2, after the portal prototype): a dense tile grid, two columns even on a
   phone, four on a computer, with tiles of different kinds (photo, pup card, green
   calendar, warm, dark) and full-width bands between them (mint, deep green, paper), each
   kind once a page, so a scroll never reads as a stack of identical cards. */
.bleed { margin: 0 calc(-1 * var(--gut)); border-radius: 0; }
@media (min-width: 720px) { .bleed { margin: 0; border-radius: var(--rc); } }
.hero { position: relative; min-height: 13rem; display: flex; flex-direction: column; justify-content: flex-end; overflow: hidden; background: var(--band); }
.hero.bleed { margin-top: calc(-1 * var(--gut)); }
@media (min-width: 720px) { .hero { min-height: 15rem; } .hero.bleed { margin-top: 0; } }
.hero img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center 38%; }
.hero .ph { position: absolute; inset: 0; display: grid; place-items: center; color: var(--brass); }
.hero .ph svg.i { width: 9rem; height: 9rem; stroke-width: 1.1; opacity: .5; }
.hero .cap { position: relative; padding: 2.6rem 1rem .9rem; color: #FFF8EC; background: linear-gradient(rgba(0,0,0,0), rgba(0,0,0,.55) 45%, rgba(0,0,0,.78)); text-shadow: 0 1px 3px rgba(0,0,0,.5); display: grid; gap: .25rem; }
.hero .script { color: #F2DFAE; font-size: 2rem; }
.hero h1 { margin: 0; color: #fff; font-size: 1.75rem; }

.bento { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .55rem; }
@media (min-width: 720px) { .bento { gap: .7rem; } }
html[data-zoom="3"] .bento { grid-template-columns: 1fr; }
.tile { min-width: 0; border-radius: var(--rc); padding: .9rem; display: grid; gap: .45rem; align-content: start; background: var(--surface); border: 1px solid var(--line); color: var(--ink); text-decoration: none; position: relative; overflow: hidden; }
.tile p { margin: 0; }
a.tile:hover { box-shadow: var(--shadow); }
.tile.full { grid-column: 1 / -1; }
.tile.green { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.tile.green.urgent { background: var(--cal); color: #fff; }
.tile.green .eyebrow, .tile.dark .eyebrow { color: inherit; opacity: .85; }
.tile.green a:not(.btn) { color: inherit; }
.tile.warm { background: var(--sand); border-color: transparent; }
.tile.dark { background: var(--head); color: var(--head-ink); border-color: transparent; }
.tile .btn { justify-self: start; }
.ico { width: 2.6rem; height: 2.6rem; border-radius: 12px; display: grid; place-items: center; background: var(--accent-soft); color: var(--accent); flex: none; }
.ico svg.i { width: 1.5rem; height: 1.5rem; }
.ico.big { width: 3.4rem; height: 3.4rem; border-radius: 14px; }
.ico.big svg.i { width: 2.1rem; height: 2.1rem; stroke-width: 1.4; }
.tile.warm .ico { background: var(--surface); color: var(--warn); }
.tile.green .ico { background: rgba(255,255,255,.14); color: inherit; }

/* The pup card: a framed round photo, the name in script with a sex badge, two facts. */
.pup { justify-items: center; text-align: center; gap: .3rem; }
.round { width: 4.5rem; height: 4.5rem; border-radius: 50%; object-fit: cover; flex: none; }
.round.ph { display: grid; place-items: center; background: var(--band); color: var(--brass); }
.pup .round { width: 4.8rem; height: 4.8rem; border: 3px solid var(--surface); box-shadow: 0 0 0 2px var(--line); }
.pname { font-family: var(--f-script); font-size: 2.1rem; line-height: 1; display: inline-flex; align-items: center; gap: .35rem; }
.sex { display: inline-grid; place-items: center; width: 1.6rem; height: 1.6rem; border-radius: 50%; font: 700 1rem/1 var(--f-body); }
.sex.girl { background: var(--girl-soft); color: var(--girl); } .sex.boy { background: var(--boy-soft); color: var(--boy); }
.pfacts { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; font-size: .8rem; justify-items: center; }
.pfacts li { display: flex; gap: .35rem; align-items: center; }
.pfacts svg.i { width: .95rem; height: .95rem; color: var(--accent); }

/* The calendar page: the month on red, the day, the weekday. */
.calrow { display: flex; gap: .65rem; align-items: center; }
.calpage { width: 3.6rem; flex: none; border-radius: 10px; overflow: hidden; background: var(--surface); color: var(--ink); text-align: center; box-shadow: 0 2px 6px rgba(0,0,0,.18); display: grid; }
.calpage b { background: var(--cal); color: #fff; font-size: .66rem; letter-spacing: .12em; text-transform: uppercase; padding: .2rem 0; }
.calpage span { font: 500 1.7rem/1.1 var(--f-display); padding-top: .15rem; }
.calpage i { font-style: normal; font-size: .62rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--muted); padding-bottom: .3rem; }
.tile.urgent .calpage b { background: var(--head); }
.bigline { font: 500 1.45rem/1.05 var(--f-display); }
.bigline.small-line { font-size: 1.05rem; line-height: 1.2; }
.weeks { display: flex; gap: 4px; }
.weeks span { flex: 1; height: .45rem; border-radius: 4px; background: rgba(127,127,127,.3); }
.weeks span.on { background: currentColor; }
.weeks span.now { background: repeating-linear-gradient(90deg, currentColor 0 5px, transparent 5px 9px); }

/* Card colours (the owner, 2026-11-21): three, paper, green and sand, the same in light
   and dark. Each card or band has one fixed colour, and no two of the same colour sit one
   directly above the other: a new card takes a colour its neighbours don't have. Green
   is the mint (.c-green, .sec.mint), the deep green (.sec.deep, the food band) and the
   solid green tile; sand is .c-sand, .sec.sand, .band and the warm tile; paper is the
   plain card (.card, .c-paper, .sec.paper). tests/portal-colours.test.js checks each
   tab. Repeated cards (the timeline's groups, the stay's updates) take turns. */
.c-paper { background: var(--surface); border-color: var(--line); }
.c-green { background: var(--accent-soft); border-color: transparent; }
.c-sand { background: var(--sand); border-color: transparent; }
.c-sand .eyebrow, .band .eyebrow, .sec.sand .eyebrow, .tile.warm .eyebrow { color: var(--sand-brass); }
.c-sand .progress { background: var(--sand-line); }
.c-sand .contact, .c-green .contact { border-top-color: var(--sand-line); }
.c-green .ico { background: var(--surface); }

/* Bands: the sand page head (Timeline, Stay), and home's full-width sections. */
.band { background: var(--sand); border-radius: var(--rc); padding: 1.1rem 1rem; }
.band h2 { font-size: 1.45rem; }
.sec { padding: 1.3rem var(--gut) 1.4rem; display: grid; gap: .8rem; }
@media (min-width: 720px) { .sec { padding: 1.6rem 1.6rem 1.7rem; } }
.sec > * { margin: 0; }
.sec .big-h { font: 600 1.7rem/1.05 var(--f-display); letter-spacing: -.01em; }
.sec.mint { background: var(--accent-soft); }
.sec.sand { background: var(--sand); }
.sec.deep { background: var(--head); color: var(--head-ink); }
.sec.deep .eyebrow { color: #E9C77E; }
.sec.paper { background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
@media (min-width: 720px) { .sec.paper { border: 1px solid var(--line); } }
.numsteps { list-style: none; margin: 0; padding: 0; display: grid; }
.numsteps li { display: grid; grid-template-columns: 3.1rem 1fr; gap: .8rem; position: relative; padding-bottom: 1.1rem; }
.numsteps li:last-child { padding-bottom: 0; }
.numsteps li:not(:last-child)::before { content: ""; position: absolute; left: 1.5rem; top: 3.2rem; bottom: .25rem; width: 2px; background: var(--accent); opacity: .45; }
.numsteps .num { width: 3rem; height: 3rem; display: grid; place-items: center; background: var(--accent); color: var(--accent-ink); font: 700 1.45rem/1 var(--f-display); border-radius: 48% 52% 46% 54% / 55% 45% 55% 45%; transform: rotate(-4deg); }
.numsteps li.done .num { background: var(--ok); }
.numsteps .num svg.i { width: 1.5rem; height: 1.5rem; stroke-width: 2.5; }
.numsteps h3 { font: 600 1.15rem/1.15 var(--f-display); margin: 0; }
.numsteps p { font-size: .9rem; margin: .2rem 0 0; }
.numsteps .btn, .numsteps .acts { margin-top: .4rem; }

/* Highlight rows: a round outlined badge, then the words (status page, programs). */
.hl { list-style: none; margin: 0; padding: 0; display: grid; gap: .9rem; }
.hl > li > div:only-child { display: grid; grid-template-columns: 3.4rem 1fr; gap: .8rem; align-items: center; }
.hl .badge { width: 3.4rem; height: 3.4rem; border-radius: 50%; border: 2.5px solid var(--accent); color: var(--accent); display: grid; place-items: center; }
.hl .badge svg.i { width: 1.8rem; height: 1.8rem; }
.hl b { font-size: .98rem; display: block; }
/* What came home in the puppy's bag (Records): the badge, the words, its button. */
.hl.bag > li > div { display: grid; grid-template-columns: 3.4rem 1fr auto; gap: .8rem; align-items: center; }
.hl.bag .small { display: block; }
.programs li { display: grid; grid-template-columns: 3.4rem 1fr; gap: .8rem; align-items: start; }
.programs p { margin: .1rem 0; }
.programs .st { margin-top: .2rem; }
.code strong { font-family: ui-monospace, Menlo, monospace; letter-spacing: .05em; }
.go { display: inline-flex; align-items: center; gap: .25rem; font-weight: 700; text-decoration: none; }
.go svg.i { width: 1rem; height: 1rem; }

/* Quick links: small square tiles, three across. */
.qgrid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .45rem; }
@media (min-width: 720px) { .qgrid { grid-template-columns: repeat(6, minmax(0, 1fr)); } }
.qtile { display: grid; justify-items: center; gap: .35rem; padding: .65rem .2rem .55rem; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; color: var(--ink); text-decoration: none; text-align: center; font-size: .76rem; font-weight: 700; line-height: 1.15; }
.qtile:hover { border-color: var(--accent); box-shadow: var(--shadow); }
@media (prefers-reduced-motion: no-preference) { .qtile, .tile { transition: box-shadow .2s, border-color .2s; } }
.contacts { display: grid; gap: .9rem; }
.contacts h2 { margin-bottom: 0; }
.contact { display: grid; gap: .45rem; padding-top: .8rem; border-top: 1px solid var(--line); }
.contact p { margin: 0; }
.contact .row .btn { flex: 1 1 7rem; }
.disclose { color: var(--muted); font-size: .76rem; padding: .2rem .2rem 0; margin: 0; }

.facts { display: grid; grid-template-columns: 1fr 1fr; gap: .6rem 1rem; margin: 0; }
.facts dt { font-size: .7rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--brass); }
.facts dd { margin: 0; }
.records { width: 100%; border-collapse: collapse; font-size: .92rem; }
.records th { text-align: left; font-size: .7rem; letter-spacing: .1em; text-transform: uppercase; color: var(--brass); padding: .3rem .3rem .3rem 0; }
.records td { border-top: 1px solid var(--line); padding: .5rem .5rem .5rem 0; vertical-align: top; }
.links { list-style: none; padding: 0; margin: 0 0 .6rem; display: grid; gap: .5rem; }
.links a { display: inline-flex; align-items: center; gap: .4rem; font-weight: 700; }
.gallery { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
@media (min-width: 720px) { .gallery { grid-template-columns: repeat(5, 1fr); } }
.gallery img { aspect-ratio: 1; width: 100%; object-fit: cover; border-radius: var(--r); }

.actionbar { position: fixed; z-index: 4; left: 0; right: 0; bottom: calc(3.75rem + env(safe-area-inset-bottom)); background: var(--surface); border-top: 1px solid var(--line); box-shadow: 0 -6px 18px rgba(0,0,0,.08); }
.actionbar .in { max-width: 64rem; margin: 0 auto; display: flex; gap: .6rem; align-items: center; padding: .45rem var(--gut); }
.actionbar .ico { width: 2.5rem; height: 2.5rem; }
.actionbar p { flex: 1; min-width: 0; margin: 0; font-size: .82rem; line-height: 1.25; }
.actionbar p b { display: block; font: 600 .98rem/1.15 var(--f-display); }
.tabs { position: fixed; z-index: 4; left: 0; right: 0; bottom: 0; display: flex; justify-content: space-around; background: var(--head); padding: .35rem .3rem calc(.35rem + env(safe-area-inset-bottom)); }
.tabs a { flex: 1; max-width: 8rem; display: grid; justify-items: center; gap: .1rem; padding: .3rem; border-radius: var(--r); color: var(--head-muted); text-decoration: none; font-size: .72rem; font-weight: 700; }
.tabs a[aria-current] { background: var(--tab-on); color: var(--tab-on-ink); }

/* Build chunk 2: the go-home checklist, the timeline, program status, the food band. */
.between { display: flex; align-items: baseline; justify-content: space-between; gap: .6rem; flex-wrap: wrap; }
.btn.small { min-height: 2.2rem; padding: .35rem .75rem; font-size: .8rem; }
.btn.text.small { min-height: 2.2rem; padding: 0; }
.acts { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem .9rem; margin-top: .35rem; }
.acts form { margin: 0; }
.st { display: inline-flex; align-items: center; gap: .35rem; font-size: .68rem; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); white-space: nowrap; }
.st::before { content: ""; width: .45rem; height: .45rem; border-radius: 50%; background: currentColor; }
.st.ok { color: var(--ok); } .st.bad { color: var(--bad); } .st.next { color: var(--accent); }
.programs li.done b { color: var(--muted); }

.progress { height: 6px; margin: .1rem 0 .3rem; background: var(--band); border-radius: 3px; overflow: hidden; }
.progress i { display: block; height: 100%; background: var(--accent); }
.checks { list-style: none; padding: 0; margin: 0; columns: 2 10.5rem; column-gap: 1rem; }
.checks li { break-inside: avoid; display: flex; align-items: flex-start; gap: .55rem; padding: .3rem 0; }
.checks li > span { flex: 1; padding-top: .3rem; font-size: .86rem; line-height: 1.3; }
.checks li.done > span { color: var(--muted); text-decoration: line-through; text-decoration-color: var(--line); }
.checks .go { padding-top: .3rem; font-size: .84rem; }
.tickf { margin: 0; }
.tick { display: grid; place-items: center; width: 1.9rem; height: 1.9rem; flex: none; padding: 0; border: 1.5px solid var(--accent); border-radius: var(--r); background: var(--surface); color: transparent; cursor: pointer; }
.tick svg.i { width: 1.1rem; height: 1.1rem; stroke-width: 2.6; }
.tick[aria-pressed="true"], a.tick.on { background: var(--accent); color: var(--accent-ink); }
a.tick:not(.on) { border-style: dashed; }

.tasks { list-style: none; padding: 0; margin: 0; }
.task { display: grid; grid-template-columns: 2.9rem 1fr; gap: .65rem; padding: .7rem 0; border-top: 1px solid var(--line); scroll-margin-top: 4.5rem; }
.task:first-child { border-top: 0; }
.task .d { display: grid; align-content: start; justify-items: center; border-radius: 9px; background: var(--band); padding: .25rem 0 .3rem; font-size: .62rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.task .d b { font: 500 1.2rem/1 var(--f-display); color: var(--ink); letter-spacing: 0; }
.task .d svg.i { width: 1.1rem; height: 1.1rem; margin: .25rem 0; }
.task h3 { margin: 0; font: 700 .95rem/1.3 var(--f-body); }
.task p { margin: .2rem 0 0; }
.task.done h3 { color: var(--muted); }

.food .prodrow { display: grid; grid-template-columns: 4.6rem 1fr; gap: .8rem; align-items: center; }
.food .box { width: 4.6rem; height: 4.6rem; border-radius: 14px; background: #FFF8EC; color: #1F3A2A; display: grid; place-items: center; }
.food .box svg.i { width: 2.8rem; height: 2.8rem; stroke-width: 1.3; }
.food .box.pic { background: #FBF3EB; overflow: hidden; }
.food .box.pic img { width: 100%; height: 100%; object-fit: cover; display: block; }
.food .duo { display: grid; gap: .8rem; }
.food .duo.two { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .6rem; }
.food .stack { min-width: 0; display: flex; flex-direction: column; gap: .6rem; }
.food .fcard { min-width: 0; display: grid; gap: .7rem; align-content: start; }
.food .fcard > * { margin: 0; }
.food .fcard .eyebrow svg.i { width: .8rem; height: .8rem; vertical-align: -.1em; }
.food .card-h { font: 600 1.7rem/1.05 var(--f-display); letter-spacing: -.01em; }
.food .ticks { list-style: none; padding: 0; margin: 0; display: grid; gap: .35rem; font-size: .88rem; font-weight: 700; line-height: 1.25; }
.food .ticks li { display: grid; grid-template-columns: 1.2rem 1fr; gap: .45rem; align-items: start; }
.food .ticks svg.i { width: 1.1rem; height: 1.1rem; stroke-width: 2.2; margin-top: .05rem; }
.food .fcard .pill { margin-top: .2rem; }
.food .fcard .under { opacity: .85; margin-top: -.2rem; }
.food .did { margin: -.3rem 0 0; }
.food .did .btn { color: inherit; opacity: .85; padding-left: 0; }
/* Two across (or a stack on the right): each card a soft panel on the dark band, the
   words a size down to fit; buttons level at the bottom; the insurance card grows. */
.food .duo.two .fcard, .food .stack .fcard { background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .12); border-radius: var(--rc); padding: .8rem; display: flex; flex-direction: column; }
.food .stack .fcard.grow { flex: 1 0 auto; }
.food .duo.two .card-h { font-size: 1.2rem; line-height: 1.1; }
.food .duo.two .prodrow { grid-template-columns: 3.1rem minmax(0, 1fr); gap: .55rem; align-items: center; }
.food .duo.two .prodrow b { font-size: .92rem; line-height: 1.2; overflow-wrap: anywhere; }
.food .duo.two .box { width: 3.1rem; height: 3.1rem; border-radius: 11px; }
.food .duo.two .box svg.i { width: 1.8rem; height: 1.8rem; }
.food .duo.two .pill { margin-top: auto; align-self: stretch; padding: .6rem .7rem; font-size: .85rem; min-height: 2.6rem; text-align: center; }
.food .duo.two .did { margin-top: -.3rem; }
.food .duo.two .did .btn { width: 100%; justify-content: center; padding: .3rem 0; }
.food .fcard.slim { gap: .55rem; padding: .7rem .8rem; }
.food .slimrow { display: grid; grid-template-columns: 2.4rem 1fr; gap: .55rem; align-items: center; }
.food .slimrow p { opacity: .85; margin: .1rem 0 0; }
.food .slimrow b { font-size: .9rem; line-height: 1.2; }
.food .fcard.slim .box { width: 2.4rem; height: 2.4rem; border-radius: 10px; }
.food .fcard.slim .box svg.i { width: 1.4rem; height: 1.4rem; stroke-width: 1.6; }
.food .duo.two .fcard.slim .pill { margin-top: 0; }
html[data-zoom="3"] .food .duo.two { grid-template-columns: 1fr; }
@media (min-width: 720px) { .food .duo.two .card-h { font-size: 1.45rem; } .food .duo.two .prodrow { grid-template-columns: 3.6rem minmax(0, 1fr); } .food .duo.two .prodrow .box { width: 3.6rem; height: 3.6rem; } .food .duo.two .prodrow b { font-size: 1rem; } .food .duo.two .fcard { padding: 1rem; } .food .duo.two .pill { align-self: flex-start; padding: .6rem 1.4rem; } .food .duo.two .did .btn { width: auto; justify-content: flex-start; } }
.food .prodrow p { opacity: .85; margin: .15rem 0 0; }
.trio { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .5rem; text-align: center; font-size: .82rem; font-weight: 700; line-height: 1.2; }
.trio svg.i { display: block; width: 1.7rem; height: 1.7rem; margin: 0 auto .3rem; stroke-width: 2; }
html[data-zoom="3"] .trio { grid-template-columns: 1fr; }
.pill { justify-self: start; display: inline-flex; align-items: center; justify-content: center; gap: .4rem; min-height: 2.9rem; padding: .6rem 1.4rem; border-radius: 40px; font: 800 .95rem/1 var(--f-body); text-decoration: none; }
.pill.light { background: #FFF8EC; color: #1F3A2A; }
.pill svg.i { width: 1rem; height: 1rem; }

/* Build chunk 4: messages, the loss page, Account's delete. */
textarea { font: 400 1rem/1.45 var(--f-body); color: var(--ink); background: var(--surface); border: 1.5px solid var(--line); border-radius: var(--r); padding: .55rem .65rem; width: 100%; resize: vertical; }
textarea:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.acct { position: relative; }
.acct b { position: absolute; top: .15rem; right: .1rem; min-width: 1.1rem; height: 1.1rem; padding: 0 .25rem; border-radius: .6rem; background: #E9C77E; color: var(--head); font: 700 .7rem/1.1rem var(--f-body); text-align: center; }
.thread { list-style: none; padding: 0; margin: 0 0 .9rem; display: grid; gap: .6rem; }
.thread li { max-width: 34rem; padding: .6rem .8rem; border-radius: var(--rc); background: var(--band); }
.thread li.mine { justify-self: end; background: var(--accent-soft); }
.thread li p { margin: 0 0 .35rem; } .thread li p:last-child { margin: 0; }
.loss { display: grid; gap: .6rem; justify-items: start; }
.loss .round { width: 5.5rem; height: 5.5rem; }
details.card > summary { cursor: pointer; }

/* Build chunk 5: the extended stay (skills, updates). */
.skills { list-style: none; padding: 0; margin: .4rem 0 .6rem; display: grid; gap: .5rem; }
.skills li { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: .15rem .6rem; }
.skills li > span:first-child { font-weight: 700; font-size: .92rem; }
.skills li > b { grid-column: 2; text-align: right; color: var(--accent); }
.skills li > .meter { grid-column: 1; grid-row: 2; }
.skills li > .muted { grid-column: 1 / -1; }
.meter { display: inline-grid; grid-template-columns: repeat(3, 2.2rem); gap: 3px; }
.meter i { height: 6px; border-radius: 3px; background: var(--line); }
.meter i.on { background: var(--accent); }
.update .gallery { margin: .6rem 0; }
.update ul.small { padding-left: 1.1rem; margin: .4rem 0 0; }

/* Home's Read next (the prototype's readNext photo rows), into the handbook. */
.ext::after { content: " \2197"; }
.readnext { display: grid; gap: .5rem; }
.readnext h2 { margin: 0; }
.prows { display: grid; gap: .45rem; }
@media (min-width: 720px) { .prows { grid-template-columns: repeat(3, 1fr); } }
.prow { display: grid; grid-template-columns: 40% 1fr; height: 5.6rem; border-radius: var(--rc); overflow: hidden; text-decoration: none; }
.prow.words { grid-template-columns: 1fr; height: auto; min-height: 4.2rem; }
.prow .ph { position: relative; display: block; overflow: hidden; background: var(--band); }
.prow .ph img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: center 30%; }
.prow .lab { background: var(--head); color: var(--head-ink); display: flex; align-items: center; justify-content: space-between; gap: .5rem; padding: .7rem .8rem; font: 600 1.05rem/1.15 var(--f-display); }
.prow:nth-child(2) .lab { background: var(--accent); color: var(--accent-ink); }
.prow .chev { flex: none; display: inline-flex; }

/* The handbook as a flipbook (the owner's buyer-guide book, 2026-11-21): a desk, a
   cover with their puppy to boop, paper pages with a running head and a folio, a
   maroon and tan trim. handbook.js turns the pages; without it (no .hb-js on <html>)
   the cover and pages stack and scroll. The book's paper stays light in dark mode. */
.kp-body.bare {
  --desk: #e9dccb; --desk-2: #dccab4; --deskink: #2e1b1a; --book-ink: #2b1d1b; --book-muted: #6b5a55;
  --paper: #fbf6ec; --paper-edge: #efe3cf; --rule: #e2d3bb; --maroon: #6e1a2a; --cocoa: #2e1b1a; --tan: #c9a46b; --leaf: #2f6f4f;
  --bookshadow: rgba(46,27,26,.28); --lift: #e7a2ae;
  background: radial-gradient(ellipse at 50% 30%, var(--desk) 0%, var(--desk-2) 100%) fixed; color: var(--deskink); min-height: 100vh;
}
@media (prefers-color-scheme: dark) { .kp-body.bare { --desk: #1e1514; --desk-2: #2a1d1b; --deskink: #f3e6d3; --paper: #f6efe2; --paper-edge: #e6d8c1; --rule: #ddcdb3; --bookshadow: rgba(0,0,0,.55); } }
.kp-body.bare > .note { margin: var(--gut); }
.hb button { font: inherit; color: inherit; }
.hb :focus-visible { outline: 3px solid var(--leaf); outline-offset: 3px; border-radius: 6px; }
.hb [hidden] { display: none !important; }

/* Cover */
.hb-cover { min-height: 100vh; min-height: 100dvh; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 22px; text-align: center; padding: 16px; position: relative; }
.hb-out { position: absolute; top: calc(12px + env(safe-area-inset-top)); left: 16px; display: inline-flex; align-items: center; gap: .4rem; color: var(--deskink); font-weight: 700; font-size: .9rem; text-decoration: none; opacity: .8; }
.hb-out:hover { opacity: 1; }
.hb .kicker { margin: 0; font: 700 .78rem/1 var(--f-body); letter-spacing: .16em; text-transform: uppercase; opacity: .75; }
.hb-cover h1 { font: 700 clamp(2.2rem, 7vw, 3.6rem)/1.02 var(--f-display); margin: 0; color: var(--deskink); }
.hb-cover h1 span { color: var(--maroon); font-style: italic; }
@media (prefers-color-scheme: dark) { .hb-cover h1 span { color: var(--lift); } }
.boop { position: relative; display: flex; flex-direction: column; align-items: center; text-decoration: none; color: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.boop .face { width: clamp(170px, 42vw, 230px); aspect-ratio: 1; border-radius: 50%; overflow: hidden; object-fit: cover; display: block; border: 6px solid var(--paper); box-shadow: 0 14px 34px var(--bookshadow), 0 0 0 2px var(--tan); transform-origin: 50% 90%; animation: hb-peek 3.6s ease-in-out infinite; background: var(--paper); }
.boop .face.nopic { display: grid; place-items: center; color: var(--tan); }
.boop .face.nopic svg { width: 45%; height: 45%; }
.boop .collar { width: clamp(120px, 30vw, 160px); height: 14px; margin-top: -30px; border-radius: 8px; background: var(--maroon); box-shadow: inset 0 -3px 0 rgba(0,0,0,.25); position: relative; z-index: 1; }
.boop .tag { position: relative; z-index: 1; margin-top: -2px; display: flex; align-items: center; gap: 8px; padding: 10px 18px 10px 14px; background: linear-gradient(160deg, #f1d9a0, var(--tan)); color: var(--cocoa); border-radius: 999px 999px 999px 999px / 60% 60% 999px 999px; font: 700 1rem/1 var(--f-display); box-shadow: 0 6px 14px var(--bookshadow); transform-origin: 50% -8px; animation: hb-swing 3.6s ease-in-out infinite; }
.boop .tag::before { content: ""; width: 9px; height: 9px; border-radius: 50%; background: var(--cocoa); opacity: .5; }
.boop:hover .face, .boop:focus-visible .face { animation: hb-wiggle .6s ease-in-out infinite; }
.boop.booped .face { animation: hb-hop .55s cubic-bezier(.3,1.6,.5,1) 1; }
.hb-cover .hint { margin: 0; font-size: .9rem; opacity: .75; max-width: 30ch; }
.heart { position: absolute; pointer-events: none; font-size: 22px; color: var(--maroon); animation: hb-float 1s ease-out forwards; }
@keyframes hb-peek { 0%, 100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-6px) rotate(-2deg); } }
@keyframes hb-swing { 0%, 100% { transform: rotate(4deg); } 50% { transform: rotate(-4deg); } }
@keyframes hb-wiggle { 0%, 100% { transform: rotate(-4deg); } 50% { transform: rotate(4deg); } }
@keyframes hb-hop { 0% { transform: translateY(0) scale(1); } 40% { transform: translateY(-26px) scale(1.06,.96); } 100% { transform: translateY(0) scale(1); } }
@keyframes hb-float { from { opacity: 1; transform: translate(0,0) scale(.6); } to { opacity: 0; transform: translate(var(--dx, 0), -90px) scale(1.3); } }

/* Reader */
.hb-reader { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 10px 16px 12px; }
.hb .bar { flex: none; position: relative; z-index: 10; width: 100%; max-width: 1100px; display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.hb .mini { width: 44px; height: 44px; border-radius: 50%; overflow: hidden; border: 3px solid var(--paper); box-shadow: 0 3px 8px var(--bookshadow); background: var(--paper); flex: none; display: grid; place-items: center; color: var(--tan); }
.hb .mini img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hb .mini:hover img { animation: hb-wiggle .6s ease-in-out infinite; }
.hb .bar .ttl { font: 700 1rem/1.1 var(--f-display); flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hb .pill { border: 1.5px solid currentColor; background: transparent; border-radius: 999px; padding: 8px 14px; font-weight: 700; cursor: pointer; font-size: .88rem; flex: none; color: var(--deskink); text-decoration: none; }
.hb .pill:hover { background: color-mix(in srgb, currentColor 12%, transparent); }
.hb .stage { width: 100%; display: grid; justify-items: center; gap: 14px; position: relative; z-index: 1; }
.hb .controls, .hb #hb-toc { display: none; }

/* A page: paper, a running head, the words, a folio. */
.hb .page { position: relative; display: flex; flex-direction: column; color: var(--book-ink); background: var(--paper); font-size: var(--fs, 15px); line-height: 1.45; width: min(100%, 34rem); min-height: 24rem; border-radius: 6px 10px 10px 6px; box-shadow: inset 10px 0 14px -12px rgba(0,0,0,.3), 0 10px 24px var(--bookshadow); }
.hb .runhead { display: flex; justify-content: space-between; gap: 8px; padding: .9em 0 .5em; margin-inline: 1.4em; font: 700 .68em/1.2 var(--f-body); letter-spacing: .12em; text-transform: uppercase; color: var(--maroon); border-bottom: 1px solid var(--rule); min-height: 2.6em; }
.hb .content { flex: 1; min-height: 0; overflow-y: auto; padding: 1em 1.4em .6em; display: flex; flex-direction: column; gap: .75em; scrollbar-width: thin; }
.hb .folio { text-align: center; font: 700 .72em/1 var(--f-body); color: var(--book-muted); padding: .4em 0 .9em; font-variant-numeric: tabular-nums; }
.hb .page h2 { font: 700 1.45em/1.1 var(--f-display); margin: 0; color: var(--cocoa); text-wrap: balance; }
.hb .page h3 { font: 700 1.08em/1.2 var(--f-display); margin: .4em 0 0; color: var(--maroon); }
.hb .page p { margin: 0; }
.hb .page ul { margin: 0; padding-left: 1.1em; display: flex; flex-direction: column; gap: .35em; }
.hb .page li::marker { color: var(--maroon); }
.hb .page a:not(.btn) { color: var(--leaf); font-weight: 700; text-decoration-thickness: 1.5px; text-underline-offset: 2px; }
.hb .page .btn.line { align-self: flex-start; color: var(--leaf); border-color: var(--leaf); background: transparent; }
.hb .page .btn.line:hover { background: var(--leaf); color: #fff; }
.hb .page .tip { font-size: .9em; color: var(--book-muted); }
.hb .page .disclose { font-size: .78em; padding: 0; margin-top: auto; }
.hb .titlepage .content { justify-content: center; text-align: center; align-items: center; gap: 1em; }
.hb .titlepage .badge { width: 7.5em; aspect-ratio: 1; border-radius: 50%; overflow: hidden; border: 4px solid var(--paper-edge); box-shadow: 0 0 0 2px var(--tan); display: grid; place-items: center; color: var(--tan); }
.hb .titlepage .badge img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hb .titlepage h2 { font-size: 2em; }
.hb .titlepage p { max-width: 34ch; }
.hb .toc { list-style: none; padding: 0 !important; margin: 0; display: flex; flex-direction: column; gap: .15em !important; }
.hb .toc a { display: flex; gap: .5em; justify-content: space-between; text-decoration: none !important; color: var(--book-ink) !important; font-weight: 400 !important; padding: .3em 0; border-bottom: 1px dotted var(--rule); }
.hb .toc a:hover { color: var(--leaf) !important; }
.hb .toc a span:last-child { font-variant-numeric: tabular-nums; color: var(--book-muted); }
.hb .blank { background: repeating-linear-gradient(135deg, transparent 0 22px, rgba(110,26,42,.035) 22px 23px), var(--paper); }
.hb .blank .content { justify-content: center; align-items: center; color: var(--book-muted); text-align: center; }
.hb .happy { font: 700 1.6em/1.1 var(--f-display); color: var(--maroon); }

/* The book, once handbook.js runs: only the cover or the reader, filling the screen. */
:host(.hb-js), :host(.hb-js) .kp-body.bare { height: 100%; overflow: hidden; }
:host(.hb-js) .hb-cover { height: 100vh; height: 100dvh; min-height: 0; }
:host(.hb-js) .hb-reader { height: 100vh; height: 100dvh; padding-bottom: calc(12px + env(safe-area-inset-bottom)); }
:host(.hb-js) .hb .stage { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; }
:host(.hb-js) .hb .controls { display: flex; align-items: center; gap: 14px; flex: none; position: relative; z-index: 10; }
:host(.hb-js) .hb #hb-toc { display: inline-block; }
:host(.hb-js) .hb .book { position: relative; transition: transform .45s cubic-bezier(.4,.1,.2,1); touch-action: pan-y; user-select: none; -webkit-user-select: none; }
:host(.hb-js) .hb .slot, :host(.hb-js) .hb .flip { position: absolute; top: 0; height: 100%; background: var(--paper); overflow: hidden; contain: layout paint; }
:host(.hb-js) .hb .slot .page, :host(.hb-js) .hb .flip .page { position: absolute; inset: 0; width: auto; min-height: 0; border-radius: 0; box-shadow: none; }
:host(.hb-js) .hb .spread .l { left: 0; width: 50%; border-radius: 10px 2px 2px 10px; box-shadow: inset -18px 0 22px -18px rgba(0,0,0,.28), 0 10px 24px var(--bookshadow); }
:host(.hb-js) .hb .spread .r { left: 50%; width: 50%; border-radius: 2px 10px 10px 2px; box-shadow: inset 18px 0 22px -18px rgba(0,0,0,.28), 0 10px 24px var(--bookshadow); }
:host(.hb-js) .hb .single .slot, :host(.hb-js) .hb .single .flip { left: 0; width: 100%; border-radius: 6px 10px 10px 6px; box-shadow: inset 10px 0 14px -12px rgba(0,0,0,.3), 0 10px 24px var(--bookshadow); }
:host(.hb-js) .hb .flip { z-index: 3; will-change: transform; pointer-events: none; }
:host(.hb-js) .hb .flip.r, :host(.hb-js) .hb .single .flip { transform-origin: left center; }
:host(.hb-js) .hb .flip.l { transform-origin: right center; }
.hb .shade { position: absolute; inset: 0; background: #000; opacity: 0; pointer-events: none; z-index: 5; }
.hb .nav { width: 46px; height: 46px; border-radius: 50%; border: 0; background: var(--maroon); color: #fff !important; font-size: 1.3rem; cursor: pointer; box-shadow: 0 4px 10px var(--bookshadow); display: grid; place-items: center; }
.hb .nav:disabled { opacity: .35; cursor: default; }
.hb .count { font: 700 .9rem/1 var(--f-body); font-variant-numeric: tabular-nums; min-width: 9ch; text-align: center; }

/* Her styles inside a chapter: big and small headings, centered lines, a note in a box,
   a fold that opens, numbered lists, photos with a caption (handbook.js bodyHtml). */
.hb .page h3.big { font-size: 1.3em; color: var(--cocoa); }
.hb .page h3.small { font-size: .98em; color: var(--book-ink); }
.hb .page .center { text-align: center; align-self: stretch; }
.hb .page strong { color: var(--cocoa); }
.hb .page ol { margin: 0; padding-left: 1.4em; display: flex; flex-direction: column; gap: .35em; }
.hb .page ol li::marker { color: var(--maroon); font-weight: 700; }
.hb .page .note { background: #f4e6d4; border: 1.5px solid var(--tan); border-radius: 10px; padding: .6em .8em; color: var(--maroon); display: flex; flex-direction: column; gap: .4em; }
.hb .page .note strong { color: inherit; }
.hb .page details.fold { border: 1.5px solid var(--rule); border-radius: 10px; background: color-mix(in srgb, var(--paper-edge) 45%, var(--paper)); }
.hb .page details.fold summary { cursor: pointer; list-style: none; display: flex; justify-content: space-between; gap: .6em; padding: .55em .8em; font: 700 1em/1.25 var(--f-display); color: var(--cocoa); }
.hb .page details.fold summary::-webkit-details-marker { display: none; }
.hb .page details.fold summary::after { content: "+"; color: var(--maroon); font-family: var(--f-body); }
.hb .page details.fold[open] summary::after { content: "\2013"; }
.hb .page details.fold .inner { padding: 0 .8em .7em; display: flex; flex-direction: column; gap: .6em; }
.hb .page figure.hbphoto { margin: 0; align-self: center; display: flex; flex-direction: column; align-items: center; gap: .35em; max-width: 100%; }
.hb .page figure.hbphoto img { display: block; max-width: 100%; max-height: var(--shotmax, 260px); width: auto; height: auto; border-radius: 8px; border: 4px solid #fff; box-shadow: 0 0 0 1.5px var(--tan), 0 6px 14px rgba(46,27,26,.18); }
.hb .page figcaption { font-size: .86em; font-style: italic; color: var(--book-muted); text-align: center; }

/* Search, on the Contents page and in its dialog */
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.hb .hsearch input { font: inherit; font-size: 1em; color: var(--book-ink); background: #fff; border: 1.5px solid var(--rule); border-radius: 999px; padding: .55em 1em; min-height: 2.6em; width: 100%; }
.hb .hsearch input:focus { outline: 2px solid var(--leaf); outline-offset: 1px; }
.hb .dlg-body .hsearch { margin: 12px 0 6px; }
.hb .hits li { display: grid; gap: .1em; padding: .25em 0; border-bottom: 1px dotted var(--rule); }
.hb .hits li a { border-bottom: 0; padding-bottom: 0; }
.hb .hits .snip { color: var(--book-muted); font-size: .86em; line-height: 1.35; }
.hb .hits .snip:empty { display: none; }
.hb .nohits { padding: .6em 0; }

/* Contents, as a dialog */
.hb dialog { border: 0; border-radius: 14px; padding: 0; background: var(--paper); color: var(--book-ink); box-shadow: 0 20px 50px var(--bookshadow); max-width: min(560px, calc(100vw - 32px)); width: 100%; }
.hb dialog::backdrop { background: rgba(30,20,19,.55); }
.hb .dlg-head { display: flex; justify-content: space-between; align-items: center; padding: 14px 18px; border-bottom: 1px solid var(--rule); }
.hb .dlg-head h2 { font: 700 1.2rem/1 var(--f-display); margin: 0; color: var(--cocoa); }
.hb .dlg-body { padding: 6px 18px 18px; max-height: 70vh; overflow: auto; font-size: 15px; }
.hb .x { border: 0; background: transparent; font-size: 1.4rem; cursor: pointer; color: var(--maroon) !important; width: 40px; height: 40px; }
@media (prefers-reduced-motion: reduce) { .hb *, .hb *::before, .hb *::after { animation: none !important; transition-duration: .01ms !important; } }

/* The looks (portal/looks.js): pieces only a look other than Classic shows, each look's
   stylesheet in looks/ bringing them out. Classic keeps them hidden. */
.hico, .lookonly { display: none; }

